import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"常量与变量","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tutorials/Variable.md","filePath":"guide/tutorials/Variable.md"}`),a={name:`guide/tutorials/Variable.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="常量与变量" tabindex="-1">常量与变量 <a class="header-anchor" href="#常量与变量" aria-label="Permalink to “常量与变量”">​</a></h1><h2 id="前言与确认" tabindex="-1">前言与确认 <a class="header-anchor" href="#前言与确认" aria-label="Permalink to “前言与确认”">​</a></h2><p>简单的输出文字虽然是开发游戏的必由之路，但仅仅局限于此，决不是任何优秀的开发者所追求的目标。</p><p>制作游戏不是写小说，仅仅靠在脚本中挥洒文采只能让玩家变成“一次性的读者”。因此，我们就需要给游戏中的<strong>信息</strong>施加名为“变化”的魔法。而实现这一点的基础，就需要首先学习如何“指代”<strong>信息</strong>。</p><div class="warning custom-block"><p class="custom-block-title">教程依赖</p><p>本教程假设您已学习过<a href="./../Quick_Start.html">快速开始</a>。若您尚未学习过，我们强烈推荐您首先学习相应教程。</p></div><p>先确认一下我们现有的工程文件夹结构：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>root/</span></span>
<span class="line"><span> ├─ emuera.config</span></span>
<span class="line"><span> ├─ Emuera1824.exe</span></span>
<span class="line"><span> ├─ CSV/</span></span>
<span class="line"><span> └─ ERB/</span></span>
<span class="line"><span>     └─ System.erb</span></span></code></pre></div><p>其中，<code>System.erb</code>的代码为：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  Print</span><span style="color:#9CDCFE;"> Hello</span><span style="color:#9CDCFE;"> World</span><span style="color:#D4D4D4;">!</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><h2 id="变量的概念、定义与打印" tabindex="-1">变量的概念、定义与打印 <a class="header-anchor" href="#变量的概念、定义与打印" aria-label="Permalink to “变量的概念、定义与打印”">​</a></h2><p>首先，我们举一个很日常的例子：我的包里有3个石头，我把石头的数量打印到屏幕上：<code>Print 3</code>。同时、我包里还有3个苹果，我把苹果的数量也打印到屏幕上：<code>Print 3</code>，这样我们就得到一个脚本：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line highlighted"><span style="color:#569CD6;">  Print</span><span style="color:#B5CEA8;"> 3</span></span>
<span class="line highlighted"><span style="color:#569CD6;">  Print</span><span style="color:#B5CEA8;"> 3</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p>现在我扔掉了一个石头，也就是需要将石头的数量变为<code>2</code>，再打印出来。</p><p>……</p><p>怎么做？游戏引擎和一些记忆力不太好的开发者就产生了迷惑：”究竟哪个3是石头的数量，而哪个3是苹果的数量呢？“</p><p>为了解决这个问题，我们在脚本语言中引入了<strong>变量</strong>这个概念。</p><p>你可以把变量看作是一个“有名字的容器”。而这个容器是能够装载东西的。</p><p>我们可以产生一个名称为<code>Stone</code>的容器，并将数值<code>3</code>装进去。用脚本表示就像这样：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Stone</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 3</span></span></code></pre></div><p>同理，苹果可以这样表示：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Apple</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 3</span></span></code></pre></div><p>这样，我们前面的脚本就可以等效于：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line highlighted"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Stone</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 3</span></span>
<span class="line highlighted"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Apple</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 3</span></span>
<span class="line highlighted"><span style="color:#569CD6;">  PrintV</span><span style="color:#9CDCFE;"> Stone</span></span>
<span class="line highlighted"><span style="color:#569CD6;">  PrintV</span><span style="color:#9CDCFE;"> Apple</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p>细心的同学也许会发现：原来脚本里的<code>Print</code>关键字现在变成了<code>PrintV</code>关键字，这是为什么呢？<a href="/ecd/reference/ERB_Commands.html#print-v-s-form-forms-k-d-l-w">更多</a></p><p>其实，这个多出来的<code>V</code>就是英语 <strong>变量“Variable”</strong> 的缩写。相比于<code>Print</code>直接打印后面的原始文本，<code>PrintV</code>会打印后面的变量所装载的值。</p><p>简单举例：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">Print</span><span style="color:#9CDCFE;"> Stone</span></span>
<span class="line"><span style="color:#569CD6;">PrintV</span><span style="color:#9CDCFE;"> Stone</span></span></code></pre></div><p>放在上面的脚本上下文中会输出：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>Stone3</span></span></code></pre></div><p>十分简单就可以理解。</p><p>言归正传。我们已经为石头和苹果定义了变量，并获得了与前面的脚本等效的新脚本，在这样的情况下，我们前面所遇到的更新信息的问题就能够迎刃而解。</p><p>修改石头的值，得到完整脚本：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Stone</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 3</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Apple</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 3</span></span>
<span class="line highlighted"><span style="color:#9CDCFE;">  Stone</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 2</span></span>
<span class="line"><span style="color:#569CD6;">  PrintV</span><span style="color:#9CDCFE;"> Stone</span></span>
<span class="line"><span style="color:#569CD6;">  PrintV</span><span style="color:#9CDCFE;"> Apple</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p>得到输出：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>23</span></span></code></pre></div><p>成功！</p><p>让我们详细地看看发生了什么：</p><ul><li><code>#Dim Stone = 3</code><ul><li>我们用<code>#Dim</code>命令定义了一个<strong>变量</strong>，名称为<code>Stone</code>，并使用<code>=</code>符号将<code>3</code>装入其中；</li></ul></li><li><code>#Dim Apple = 3</code><ul><li>我们用<code>#Dim</code>命令定义了一个<strong>变量</strong>，名称为<code>Apple</code>，并使用<code>=</code>符号将<code>3</code>装入其中；</li></ul></li><li><code>Stone = 2</code><ul><li>修改<code>Stone</code>变量的值，使其变为<code>2</code>；</li></ul></li><li><code>PrintV Stone</code><ul><li>我们使用<code>PrintV</code>命令将变量名为<code>Stone</code>的值输出到屏幕上；</li></ul></li><li><code>PrintV Apple</code><ul><li>我们使用<code>PrintV</code>命令将变量名为<code>Apple</code>的值输出到屏幕上；</li></ul></li></ul><p>是不是特别简单就能理解？通过定义一个”有名字的容器“，并将没有额外信息的“值”装入其中，我们就具有了操作值的基础工具——至少我们知道了某个值的名字<code>:)</code>。</p><p>而这个“容器”，我们就称为<strong>变量</strong>。</p><p>显而易见，一个<strong>变量</strong>至少由两个部分组成：<strong>变量名</strong>和<strong>值</strong>。</p><p>这部分很简单，不再赘述。</p><h2 id="常量的概念、定义与打印" tabindex="-1">常量的概念、定义与打印 <a class="header-anchor" href="#常量的概念、定义与打印" aria-label="Permalink to “常量的概念、定义与打印”">​</a></h2><p><strong>常量</strong>是一种“不可改变的”<strong>变量</strong>。</p><div class="warning custom-block"><p class="custom-block-title">待讨论的话题</p><p>一般来说，常量相比于变量，缺少了值的修改功能，但能够提高代码执行的性能；</p><p>但我猜想，具体到 Erabasic 游戏脚本上，引擎是否能够为常量提供相比于变量更低的性能开销，还不能肯定。</p><p>因此，我目前对 Erabasic 常量的看法是：</p><blockquote><p>是来自其他语言的概念残留，脚本中可不使用该特性。</p></blockquote><p>这个观点欢迎大家探讨，也欢迎大家从源码分析和 Benchmark 两个角度来论证。</p><p>若猜想证实，未来文档会对常量进行如下处理：</p><ul><li>削减常量相关内容的占比；</li><li>避免在示例脚本中用到常量相关的内容；</li><li>在 MCS 代码风格中将常量特性列为不推荐；</li></ul><p>以进一步平滑 Erabasic 的学习曲线。</p></div><p>定义常量十分简单，完整脚本如下：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#569CD6;"> Const </span><span style="color:#9CDCFE;">Stone</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#569CD6;">  PrintV</span><span style="color:#9CDCFE;"> Stone</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p>其中<code>Const</code>关键字就代表定义类型为常量。</p><p>若尝试对常量的值进行修改，如：</p><div class="warning custom-block"><p class="custom-block-title">该代码含有可期待的错误</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">Dim</span><span style="color:#569CD6;"> Const </span><span style="color:#9CDCFE;">Stone</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#9CDCFE;">  Stone</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#569CD6;">  PrintV</span><span style="color:#9CDCFE;"> Stone</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div></div><p>会得到报错：</p><div class="danger custom-block"><p class="custom-block-title">错误信息<a href="javascript:alert(&#39;TODO&#39;)">索引</a></p><blockquote><p>代入文の左辺に変更できない変数を指定することはできません</p></blockquote><p>你不能在赋值语句的左边指定一个不能改变的变量</p></div><p>基本上就是这样。</p>`,53)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};